    "t": "p",
    "x": "脊髄損傷の神経学的重症度や回復度を把握するための評価尺度として、フランケル（Frankel）分類とASIA機能障害尺度（AIS）が広く用いられています。フランケル分類は簡便な5段階評価ですが、AISはより詳細な感覚・運動機能評価やKey muscleの筋力判定（MMT）を取り入れて国際基準（ISNCSCI）として標準化された評価法です。"
