  "description": "30秒椅子立ち上がりテスト（CS-30）と5回椅子立ち上がりテスト（5STS）の測定方法、サルコペニア診断や転倒リスク評価で用いられるカットオフ値、年代別基準値を解説。資料ごとに異なる測定条件や基準値の併記まとめ。",
