    "t": "p",
    "x": "回復期リハビリテーション病棟は、脳血管疾患又は大腿骨頸部骨折等の患者に対して、ADLの向上による寝たきりの防止と家庭復帰を目的としたリハビリテーションを集中的に行う病棟です（留意事項通知）。令和8年度診療報酬改定で、入院料の点数、実績指数の基準・計算方法などが見直されました。"
