  "description": "脳卒中等の痙縮評価に用いられるModified Ashworth Scale（MAS）の6段階判定基準、1と1+の鑑別、正しい測定手順、信頼性やMDC等の指標を理学療法士・学生向けにわかりやすく解説します。",
