    "x": "サルコペニアは加齢や活動低下、疾患、栄養不良に伴って骨格筋量の減少と筋力または身体機能の低下が生じる状態です。理学療法評価やリハビリテーション介入においては、アジア人を対象としたAWGS 2019診断基準に基づき、客観的なカットオフ値を用いて早期発見・重症度判定を行い、運動療法と栄養療法を組み合わせた包括的なアプローチを進めることが重要です。"
