    "x": "SIASの合計点（76点満点）による重症度分類の目安としては、30点以下が重度、31〜50点が中等度、51点以上が軽度とされています。また、回復期リハビリテーション病棟における退院時歩行自立に関する研究では、入棟時カットオフ値としてSIAS総点59点、下肢運動9点、体幹3点、感覚9点といった値が算出・報告されています。"
