  "description": "10m歩行テストの実施手順、快適・最大歩行速度の違い、歩行速度別のカットオフ値やMDC・MCIDの臨床的解釈を理学療法士・学生向けに解説。予備路の設定やプロトコルによる差異、補助具条件の記録上の注意点まで網羅しています。",
